def simplify_path(path):
    stack = []
    for part in path.split("/"):
        if part == "" or part == ".":
            continue                # empty pieces and "." change nothing
        if part == "..":
            if stack:
                stack.pop()         # up one level, never above the root
        else:
            stack.append(part)
    return "/" + "/".join(stack)

print(simplify_path("/a/./b/../c"))        # /a/c
print(simplify_path("/home/user/../.."))   # /

